const PLAYERS = ["ゆか", "たけ"];
let answererIndex = Number(localStorage.getItem("wordHunterAnswerer") || 0) % PLAYERS.length;

let selectedPlayers = ["ゆか","たけ"];
let answerOrder = [];
let currentAnswererIndex = 0;
let roundNumber = 1;

function shuffleArray(arr){
  const a=[...arr];
  for(let i=a.length-1;i>0;i--){
    const j=Math.floor(Math.random()*(i+1));
    [a[i],a[j]]=[a[j],a[i]];
  }
  return a;
}

function getSelectedPlayers(){
  return [...document.querySelectorAll(".playerCheck:checked")].map(el=>el.value);
}

function updateOrderPreview(){
  const el=document.getElementById("orderPreview");
  if(!el) return;
  if(!answerOrder.length){ el.style.display="none"; return; }
  el.style.display="";
  el.textContent="今回の回答者順： " + answerOrder.map((n,i)=>`${i+1}. ${n}`).join(" → ");
}

function currentAnswerer(){
  return answerOrder[currentAnswererIndex] || selectedPlayers[0] || "回答者";
}

function updateRoundLabels(){
  const a=currentAnswerer();
  const round=document.getElementById("roundInfo");
  const ans=document.getElementById("answererName");
  const wp=document.getElementById("wordPlayer");
  if(round) round.textContent=`ROUND ${roundNumber}　回答者：${a}`;
  if(ans) ans.textContent=`今回の回答者：${a}`;
  if(wp && /ゆか|たけ|回答者/.test(wp.textContent||"")) wp.textContent=a;
}
let currentTopic = null;
let timeLimit = 300, timeLeft = 300, timerId = null, paused = false, audioCtx = null;
let changed = false;
const $ = s => document.querySelector(s);
const screens = [...document.querySelectorAll(".screen")];

function showScreen(id){ screens.forEach(s=>s.classList.toggle("active",s.id===id)); window.scrollTo({top:0,behavior:"instant"}); }
function formatTime(sec){ sec=Math.max(0,sec); return String(Math.floor(sec/60)).padStart(2,"0")+":"+String(sec%60).padStart(2,"0"); }
function randomTopic(){ return TOPICS[Math.floor(Math.random()*TOPICS.length)]; }
function answerer(){ return PLAYERS[answererIndex]; }
function questioner(){ return PLAYERS[(answererIndex+1)%PLAYERS.length]; }
function newRound(){ currentTopic=randomTopic(); changed=false; }
function fitSecretWord(){ const el=$("#secretWord"), n=(el.textContent||"").length; const z=n<=6?58:n<=10?48:n<=15?39:n<=22?32:27; el.style.fontSize=`min(${z}px, ${Math.max(7.2,z/5.8)}vw)`; }
function setPassScreen(){ $("#passTitle").textContent=answerer()+"へ"; $("#passMessage").textContent=answerer()+"だけが画面を見てください。ほかの人は見ないでください。"; $("#showWordBtn").textContent="お題を確認する"; }
function unlockAudio(){ try{ audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)(); if(audioCtx.state==="suspended") audioCtx.resume(); }catch(e){} }
function cue(freq=760,duration=.11){ try{ unlockAudio(); const now=audioCtx.currentTime,o=audioCtx.createOscillator(),g=audioCtx.createGain(); o.type="sine";o.frequency.value=freq;o.connect(g);g.connect(audioCtx.destination);g.gain.setValueAtTime(.001,now);g.gain.exponentialRampToValueAtTime(.12,now+.015);g.gain.exponentialRampToValueAtTime(.001,now+duration);o.start(now);o.stop(now+duration+.02);}catch(e){} }
function alarm(){ [0,200,400,680].forEach((d,i)=>setTimeout(()=>cue(i===3?900:650,.17),d)); }
function updateTimerStyle(){ document.body.classList.toggle("warning",timeLeft<=60&&timeLeft>30); document.body.classList.toggle("danger",timeLeft<=30&&timeLeft>0); }
function stopTimer(){ clearInterval(timerId); timerId=null; }
function goAnswer(){ stopTimer(); $("#oralPrompt").textContent=`質問タイム終了！ ${answerer()}のお題を発表します。`; showScreen("answer"); }
function startTimer(){ stopTimer();paused=false;$("#pauseBtn").textContent="一時停止";timeLeft=timeLimit;$("#timer").textContent=formatTime(timeLeft);updateTimerStyle();timerId=setInterval(()=>{if(paused)return;timeLeft--;$("#timer").textContent=formatTime(timeLeft);updateTimerStyle();if(timeLeft>30&&timeLeft<timeLimit&&timeLeft%60===0)cue(620,.14);if(timeLeft===30){cue(780,.28);setTimeout(()=>cue(780,.20),180);}if(timeLeft>=1&&timeLeft<=10)cue(timeLeft<=3?1040:920,timeLeft<=3?.18:.10);if(timeLeft<=0){stopTimer();alarm();setTimeout(goAnswer,700);}},1000); }
function openRules(){ $("#rulesModal").classList.add("open");$("#rulesModal").setAttribute("aria-hidden","false"); }
function closeRules(){ $("#rulesModal").classList.remove("open");$("#rulesModal").setAttribute("aria-hidden","true"); }

$("#rulesBtn").addEventListener("click",openRules); $("#gameRulesBtn").addEventListener("click",openRules); $("#closeRulesBtn").addEventListener("click",closeRules); document.querySelector("[data-close-modal]").addEventListener("click",closeRules);
$("#minusTime").addEventListener("click",()=>{timeLimit=Math.max(60,timeLimit-30);$("#timeSetting").textContent=formatTime(timeLimit);});
$("#plusTime").addEventListener("click",()=>{timeLimit=Math.min(3600,timeLimit+30);$("#timeSetting").textContent=formatTime(timeLimit);});
$("#startBtn").addEventListener("click",()=>{unlockAudio();newRound();setPassScreen();showScreen("pass");});
$("#showWordBtn").addEventListener("click",()=>{$("#wordPlayer").textContent=answerer()+"のお題";$("#secretWord").textContent=currentTopic.topic;$("#secretGenre").textContent="ジャンル："+currentTopic.genre;$("#changeWordBtn").disabled=changed;$("#changeWordBtn").textContent=changed?"✓ お題変更は使用済み":"🔄 お題を1回だけ変更";$("#changeWordHint").textContent=changed?"このラウンドは変更済みです。":"知らないお題なら1回だけ変更できます。";fitSecretWord();updateRoundLabels();
  showScreen("word");});
$("#changeWordBtn").addEventListener("click",()=>{if(changed)return;let n=randomTopic();while(n.topic===currentTopic.topic)n=randomTopic();currentTopic=n;changed=true;$("#secretWord").textContent=n.topic;$("#secretGenre").textContent="ジャンル："+n.genre;$("#changeWordBtn").disabled=true;$("#changeWordBtn").textContent="✓ お題変更は使用済み";$("#changeWordHint").textContent="新しいお題に変更しました。";fitSecretWord();});
$("#hideWordBtn").addEventListener("click",()=>{$("#secretWord").textContent="● ● ●";$("#secretGenre").textContent="お題は非表示です";$("#handoffText").textContent=`${answerer()}がお題を確認しました。画面をみんなで見られる位置に戻してください。`;$("#handoffBtn").textContent="質問タイム開始";showScreen("handoff");});
$("#handoffBtn").addEventListener("click",()=>{$("#gameGuide").textContent=`回答者：${answerer()}　質問者：${questioner()}（大人数なら、ほかの人も一緒に質問できます）`;showScreen("game");startTimer();});
$("#extendBtn").addEventListener("click",()=>{timeLeft=Math.min(3600,timeLeft+60);$("#timer").textContent=formatTime(timeLeft);updateTimerStyle();});
$("#pauseBtn").addEventListener("click",()=>{paused=!paused;$("#pauseBtn").textContent=paused?"再開":"一時停止";});
$("#answerBtn").addEventListener("click",goAnswer);
$("#oralNextBtn").addEventListener("click",()=>{$("#resultTitle").textContent="正解発表！";$("#resultBody").innerHTML=`<div class="answer-box reveal-pop"><b>${answerer()}のお題</b><br><strong>${currentTopic.topic}</strong><br><span>${currentTopic.genre}</span></div>`;$("#revealNextBtn").style.display="none";$("#againBtn").style.display="";showScreen("result");cue(880,.16);});
$("#againBtn").addEventListener("click",()=>{answererIndex=(answererIndex+1)%PLAYERS.length;localStorage.setItem("wordHunterAnswerer",String(answererIndex));newRound();setPassScreen();document.body.classList.remove("warning","danger");showScreen("pass");});
$("#homeBtn").addEventListener("click",()=>{stopTimer();document.body.classList.remove("warning","danger");showScreen("home");});
$("#dataStatus").textContent=`お題 ${TOPICS.length.toLocaleString()}個 準備完了`;
window.addEventListener("resize",()=>{try{fitSecretWord()}catch(e){}}); window.addEventListener("orientationchange",()=>setTimeout(()=>{try{fitSecretWord()}catch(e){}},150));

const toggleAllPlayersBtn=document.getElementById("toggleAllPlayersBtn");
if(toggleAllPlayersBtn){
  toggleAllPlayersBtn.addEventListener("click",()=>{
    const boxes=[...document.querySelectorAll(".playerCheck")];
    const allOn=boxes.every(b=>b.checked);
    boxes.forEach(b=>b.checked=!allOn);
  });
}

function advanceAnswerer(){
  if(!answerOrder.length) return;
  currentAnswererIndex++;
  if(currentAnswererIndex>=answerOrder.length){
    currentAnswererIndex=0;
    answerOrder=shuffleArray(selectedPlayers);
    roundNumber++;
    updateOrderPreview();
  } else {
    roundNumber++;
  }
  updateRoundLabels();
}

function buildGenreList(){
  const counts={};
  TOPICS.forEach(item=>{const g=item.genre||"その他";counts[g]=(counts[g]||0)+1;});
  const entries=Object.entries(counts).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0],"ja"));
  const body=document.getElementById("genreListBody");
  const summary=document.getElementById("genreSummary");
  if(!body||!summary)return;
  summary.textContent=`全${TOPICS.length}お題・${entries.length}ジャンル`;
  body.innerHTML=entries.map(([name,count])=>`<div class="genre-row"><span class="genre-name">${name}</span><span class="genre-count">${count}個</span></div>`).join("");
}
function openGenreModal(){
  buildGenreList();
  const m=document.getElementById("genreModal");
  if(!m)return;
  m.classList.add("open");
  m.setAttribute("aria-hidden","false");
}
function closeGenreModal(){
  const m=document.getElementById("genreModal");
  if(!m)return;
  m.classList.remove("open");
  m.setAttribute("aria-hidden","true");
}
document.addEventListener("click",(e)=>{
  const target=e.target.closest("#genreListBtn,#closeGenreModalBtn,[data-close-genre-modal]");
  if(!target)return;
  e.preventDefault();
  if(target.matches("#genreListBtn")) openGenreModal();
  else closeGenreModal();
});
document.addEventListener("keydown",(e)=>{
  if(e.key==="Escape") closeGenreModal();
});
